DIRECTIVE_PREFIXES = (
    "noqa", "type:", "pyright:", "mypy:", "ruff:", "fmt:",
    "isort:", "pragma:", "nosec", "coverage:", "mechanism-ok:",
    "raw-git-ok:", "tickets-boundary-ok:", "read-via:",
)

def source(ref, path):
    return subprocess.check_output(["git", "show", f"{ref}:{path}"], text=True)

def parse(raw, path):
    return ast.parse(raw, filename=path, type_comments=True)

def qualified_nodes(tree):
    found = [("module", tree)]
    def walk(node, prefix=""):
        for child in getattr(node, "body", []):
            if isinstance(child, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                owner = f"{prefix}.{child.name}" if prefix else child.name
                found.append((owner, child))
                walk(child, owner)
    walk(tree)
    return found

def normalize(raw, path):
    tree = parse(raw, path)
    seen = set()
    for owner, node in qualified_nodes(tree):
        body = getattr(node, "body", [])
        is_doc = (
            body
            and isinstance(body[0], ast.Expr)
            and isinstance(body[0].value, ast.Constant)
            and isinstance(body[0].value.value, str)
        )
        if owner in DOCS[path]:
            assert is_doc, ("allowlisted docstring missing", path, owner)
            body[0].value.value = "__ALLOWLISTED_PROSE__"
            seen.add(owner)
    assert seen == DOCS[path], ("docstring allowlist mismatch", path, sorted(DOCS[path] - seen))
    for node in ast.walk(tree):
        if isinstance(node, ast.TypeIgnore):
            node.lineno = 0
    return ast.dump(tree, include_attributes=False)

def owner_ranges(tree):
    ranges = []
    for owner, node in qualified_nodes(tree):
        if owner == "module":
            continue
        start = getattr(node, "lineno", 1)
        end = getattr(node, "end_lineno", start)
        ranges.append((start, end, owner))
    return ranges

def owner_for(line, ranges):
    candidates = [item for item in ranges if item[0] <= line <= item[1]]
    if not candidates:
        return "module"
    return min(candidates, key=lambda item: item[1] - item[0])[2]

def comment_blocks(raw, path):
    tree = parse(raw, path)
    ranges = owner_ranges(tree)
    lines = raw.splitlines()
    blocks = []
    for token in tokenize.generate_tokens(io.StringIO(raw).readline):
        if token.type != tokenize.COMMENT:
            continue
        row, column = token.start
        owner = owner_for(row, ranges)
        full_line = not lines[row - 1][:column].strip()
        item = (row, column, token.string, owner, full_line)
        if blocks:
            previous = blocks[-1][-1]
            joins = (
                full_line
                and previous[4]
                and row == previous[0] + 1
                and column == previous[1]
                and owner == previous[3]
            )
            if joins:
                blocks[-1].append(item)
                continue
        blocks.append([item])

    ordinals = collections.defaultdict(int)
    result = []
    for block in blocks:
        owner = block[0][3]
        ordinal = ordinals[owner]
        ordinals[owner] += 1
        tokens = tuple((item[1], item[2]) for item in block)
        result.append((owner, ordinal, tokens))
    return result

def selected_positions(blocks, path):
    selected = set()
    for anchor in ANCHORS.get(path, []):
        matches = [
            (owner, ordinal)
            for owner, ordinal, tokens in blocks
            if anchor in " ".join(text for _column, text in tokens)
        ]
        assert len(matches) == 1, ("ordinary comment anchor mismatch", path, anchor, matches)
        selected.add(matches[0])
    assert len(selected) == len(ANCHORS.get(path, [])), ("duplicate ordinary comment anchors", path)
    return selected

def counts_by_owner(blocks):
    counts = collections.Counter(owner for owner, _ordinal, _tokens in blocks)
    return dict(counts)

def canonical_comments(blocks, selected):
    result = []
    for owner, ordinal, tokens in blocks:
        if (owner, ordinal) in selected:
            result.append((owner, ordinal, "__ALLOWLISTED_PROSE__"))
        else:
            result.append((owner, ordinal, tokens))
    return result

def directive_signatures(raw):
    lines = raw.splitlines()
    found = []
    for token in tokenize.generate_tokens(io.StringIO(raw).readline):
        if token.type != tokenize.COMMENT:
            continue
        body = token.string[1:].lstrip().lower()
        if not (
            token.string.startswith("#!")
            or any(body.startswith(prefix) for prefix in DIRECTIVE_PREFIXES)
        ):
            continue
        row, column = token.start
        left = lines[row - 1][:column].rstrip()
        attachment = ("inline", left) if left else ("next", "<EOF>")
        if not left:
            for line in lines[row:]:
                stripped = line.strip()
                if stripped and not stripped.startswith("#"):
                    attachment = ("next", stripped)
                    break
        found.append((token.string, attachment))
    return found

directive_total = 0
selected_total = 0
for path in PATHS:
    before = source("HEAD^", path)
    final = source("HEAD", path)
    assert normalize(before, path) == normalize(final, path), ("AST/runtime drift", path)

    before_blocks = comment_blocks(before, path)
    final_blocks = comment_blocks(final, path)
    selected = selected_positions(before_blocks, path)
    selected_total += len(selected)
    assert counts_by_owner(before_blocks) == counts_by_owner(final_blocks), (
        "comment block count drift",
        path,
    )
    assert canonical_comments(before_blocks, selected) == canonical_comments(final_blocks, selected), (
        "non-allowlisted ordinary comment drift",
        path,
    )

    before_directives = directive_signatures(before)
    final_directives = directive_signatures(final)
    assert before_directives == final_directives, ("directive text or attachment drift", path)
    directive_total += len(before_directives)

assert selected_total == 9, ("ordinary comment allowlist size", selected_total)
assert directive_total == 26, ("directive count", directive_total)
